/* Fight Night - event slate. The one full-frame graphic that owns its background:
   near-black with a low radial lift, two faint diagonal blades echoing the stinger. */

@font-face {
  font-family: 'Archivo';
  src: url("fonts/archivo.woff2") format("woff2");
  font-weight: 100 1000;
  font-display: swap;
}
@font-face {
  font-family: 'Saira';
  src: url("fonts/saira.woff2") format("woff2");
  font-weight: 100 1000;
  font-display: swap;
}

:root {
  --scale: 1;
  --accent: #ff5a1f;
  --panel-bg: #16181d;
  --ink: #f2f4f7;
  --ink-dim: #98a1ab;
  --font-display: 'Archivo', Arial, sans-serif;
  --font-data: 'Saira', Arial, sans-serif;
}

html, body {
  margin: 0;
  width: 1920px;
  height: 1080px;
  overflow: hidden;
  background: transparent;
}

.sl-root {
  position: absolute;
  inset: 0;
  overflow: hidden;
  opacity: 0;
}

.sl-bg {
  position: absolute;
  inset: 0;
  background:
    radial-gradient(1100px 640px at 50% 38%, rgba(60, 66, 78, 0.35) 0%, transparent 62%),
    #0b0c0f;
}

/* Two faint diagonal blades - the stinger's geometry at rest. */
.sl-blade {
  position: absolute;
  top: -25%;
  height: 150%;
  width: 220px;
  transform: rotate(-14deg);
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.045), rgba(255, 255, 255, 0.015));
}

.sl-blade-l { left: 6%; }
.sl-blade-r { right: 10%; width: 90px; }

.sl-stack {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  transform: scale(var(--scale));
}

.sl-event {
  display: flex;
  align-items: baseline;
  gap: 26px;
}

.sl-event-name {
  font-family: var(--font-data);
  font-weight: 600;
  font-size: 34px;
  letter-spacing: 0.42em;
  line-height: 1;
  color: var(--ink-dim);
  text-transform: uppercase;
  transform: translateX(0.21em);
}

.sl-event-num {
  font-family: var(--font-data);
  font-weight: 700;
  font-size: 34px;
  letter-spacing: 0.12em;
  line-height: 1;
  color: var(--accent);
  font-variant-numeric: tabular-nums;
}

.sl-main {
  font-family: var(--font-display);
  font-weight: 900;
  font-size: 120px;
  letter-spacing: 0.04em;
  line-height: 1.04;
  margin-top: 34px;
  color: var(--ink);
  text-transform: uppercase;
  text-align: center;
  max-width: 1600px;
}

.sl-foot {
  display: flex;
  align-items: center;
  gap: 20px;
  margin-top: 44px;
  padding-top: 26px;
  border-top: 1px solid rgba(255, 255, 255, 0.16);
}

.sl-foot span {
  font-family: var(--font-data);
  font-weight: 500;
  font-size: 22px;
  letter-spacing: 0.18em;
  line-height: 1;
  color: var(--ink-dim);
  text-transform: uppercase;
  white-space: nowrap;
}

.sl-dot {
  width: 5px;
  height: 5px;
  background: var(--accent);
  transform: rotate(45deg);
}

template.js:
/* Fight Night - event slate. SPX lifecycle; no ?. or ?? (old CasparCG CEF). */

(function () {
  var entrance = null;

  window.update = function (data) {
    var parsed = typeof data === 'string' ? JSON.parse(data) : data;
    if (!parsed) { return; }
    for (var key in parsed) {
      var el = document.getElementById(key);
      if (el) { el.textContent = parsed[key]; }
    }
  };

  window.play = function () {
    if (entrance) { entrance.kill(); }
    entrance = gsap.timeline();
    entrance.set('#sl-root', { autoAlpha: 1 });
    entrance.from('.sl-bg', { autoAlpha: 0, duration: 0.7, ease: 'power1.out' }, 0);
    entrance.from('.sl-blade-l', { x: -140, autoAlpha: 0, duration: 0.9, ease: 'power2.out' }, 0.1);
    entrance.from('.sl-blade-r', { x: 140, autoAlpha: 0, duration: 0.9, ease: 'power2.out' }, 0.1);
    entrance.from('.sl-event', { y: -18, autoAlpha: 0, duration: 0.5, ease: 'power2.out' }, 0.35);
    entrance.from('.sl-main', { y: 28, autoAlpha: 0, duration: 0.65, ease: 'power3.out' }, 0.45);
    entrance.from('.sl-foot', { autoAlpha: 0, duration: 0.5, ease: 'power2.out' }, 0.75);
  };

  window.stop = function () {
    gsap.to('#sl-root', { autoAlpha: 0, duration: 0.55, ease: 'power2.inOut' });
  };

  window.next = function () {};
})();

template.css:
/* Fight Night - fight card rundown. A right-side card of bout rows; the operator's
   highlight is one accent-edged row, moved by Next. */

@font-face {
  font-family: 'Archivo';
  src: url("fonts/archivo.woff2") format("woff2");
  font-weight: 100 1000;
  font-display: swap;
}
@font-face {
  font-family: 'Saira';
  src: url("fonts/saira.woff2") format("woff2");
  font-weight: 100 1000;
  font-display: swap;
}

:root {
  --scale: 1;
  --accent: #ff5a1f;
  --panel-bg: #16181d;
  --panel-bg-top: #23272e;
  --strip-bg: rgba(13, 15, 19, 0.88);
  --ink: #f2f4f7;
  --ink-dim: #98a1ab;
  --edge: rgba(255, 255, 255, 0.08);
  --font-display: 'Archivo', Arial, sans-serif;
  --font-data: 'Saira', Arial, sans-serif;
}

html, body {
  margin: 0;
  width: 1920px;
  height: 1080px;
  overflow: hidden;
  background: transparent;
}

.fc-root {
  position: absolute;
  right: 96px;
  top: 50%;
  transform: translateY(-50%);
  opacity: 0;
}

.fc-panel {
  display: flex;
  flex-direction: column;
  width: 700px;
  border-top: 4px solid var(--accent);
  box-shadow: 0 24px 64px rgba(0, 0, 0, 0.5);
  transform: scale(var(--scale));
  transform-origin: right center;
}

.fc-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  padding: 26px 34px;
  background: linear-gradient(180deg, var(--panel-bg-top), var(--panel-bg));
  box-shadow: inset 0 1px 0 var(--edge);
}

.fc-title {
  font-family: var(--font-display);
  font-weight: 800;
  font-size: 32px;
  letter-spacing: 0.08em;
  line-height: 1;
  color: var(--ink);
  text-transform: uppercase;
}

.fc-badge {
  font-family: var(--font-data);
  font-weight: 700;
  font-size: 18px;
  letter-spacing: 0.26em;
  line-height: 1;
  color: var(--accent);
  text-transform: uppercase;
}

.fc-rows {
  display: flex;
  flex-direction: column;
}

.fc-row {
  display: flex;
  flex-direction: column;
  gap: 9px;
  padding: 21px 34px;
  background: var(--strip-bg);
  border-top: 1px solid rgba(255, 255, 255, 0.07);
  border-left: 4px solid transparent;
}

.fc-row.fc-live {
  background: linear-gradient(180deg, var(--panel-bg-top), var(--panel-bg));
  border-left-color: var(--accent);
}

.fc-bout {
  font-family: var(--font-display);
  font-weight: 700;
  font-size: 24px;
  letter-spacing: 0.05em;
  line-height: 1.1;
  color: var(--ink);
  text-transform: uppercase;
}

.fc-division {
  font-family: var(--font-data);
  font-weight: 500;
  font-size: 16px;
  letter-spacing: 0.22em;
  line-height: 1;
  color: var(--ink-dim);
  text-transform: uppercase;
}

template.js:
/* Fight Night - fight card rundown. Rows are built from the hidden textarea field
   (#f1, one bout per line, "Red vs Blue | Division"); Next moves the highlight down
   the card and cycles. No ?. or ?? (old CasparCG CEF). */

(function () {
  var entrance = null;
  var live = -1;

  function buildRows() {
    var holder = document.getElementById('f1');
    var host = document.getElementById('fc-rows');
    if (!holder || !host) { return; }
    var lines = holder.textContent.split('\n');
    var html = '';
    for (var i = 0; i < lines.length; i++) {
      var line = lines[i].replace(/^\s+|\s+$/g, '');
      if (!line) { continue; }
      var parts = line.split('|');
      var bout = parts[0] ? parts[0].replace(/^\s+|\s+$/g, '') : '';
      var division = parts[1] ? parts[1].replace(/^\s+|\s+$/g, '') : '';
      html += '<div class="fc-row"><span class="fc-bout"></span>' +
        (division ? '<span class="fc-division"></span>' : '') + '</div>';
      // Text lands via textContent below - never through innerHTML - so operator
      // input can't inject markup.
      void bout;
    }
    host.innerHTML = html;
    var rows = host.querySelectorAll('.fc-row');
    var r = 0;
    for (var j = 0; j < lines.length; j++) {
      var l = lines[j].replace(/^\s+|\s+$/g, '');
      if (!l) { continue; }
      var p = l.split('|');
      var row = rows[r];
      if (row) {
        row.querySelector('.fc-bout').textContent = p[0] ? p[0].replace(/^\s+|\s+$/g, '') : '';
        var div = row.querySelector('.fc-division');
        if (div) { div.textContent = p[1] ? p[1].replace(/^\s+|\s+$/g, '') : ''; }
      }
      r += 1;
    }
    highlight(live);
  }

  function highlight(index) {
    var rows = document.querySelectorAll('.fc-row');
    for (var i = 0; i < rows.length; i++) {
      if (i === index) { rows[i].className = 'fc-row fc-live'; }
      else { rows[i].className = 'fc-row'; }
    }
  }

  window.update = function (data) {
    var parsed = typeof data === 'string' ? JSON.parse(data) : data;
    if (!parsed) { return; }
    for (var key in parsed) {
      var el = document.getElementById(key);
      if (el) { el.textContent = parsed[key]; }
    }
    if ('f1' in parsed) { buildRows(); }
  };

  window.play = function () {
    if (entrance) { entrance.kill(); }
    live = -1;
    buildRows();
    entrance = gsap.timeline();
    entrance.set('#fc-root', { autoAlpha: 1 });
    entrance.fromTo('.fc-panel',
      { clipPath: 'inset(0 0 100% 0)' },
      { clipPath: 'inset(0 0 0% 0)', duration: 0.6, ease: 'power3.out' }, 0);
    entrance.from('.fc-row', { autoAlpha: 0, x: 26, duration: 0.4, ease: 'power2.out', stagger: 0.07 }, 0.2);
  };

  window.next = function () {
    var rows = document.querySelectorAll('.fc-row');
    if (!rows.length) { return; }
    live = (live + 1) % rows.length;
    highlight(live);
  };

  window.stop = function () {
    gsap.to('#fc-root', { x: 40, autoAlpha: 0, duration: 0.45, ease: 'power2.in', onComplete: function () {
      gsap.set('#fc-root', { x: 0 });
    } });
  };
})();

