/* Fight Night - matchup / versus. A lower-band composition: two fighter panels
   flanking a carbon center column; corner colors live in the name underlines. */

@font-face {
  font-family: 'Archivo';
  src: url("fonts/archivo.woff2") format("woff2");
  font-weight: 100 1000;
  font-display: swap;
}
@font-face {
  font-family: 'Saira';
  src: url("fonts/saira.woff2") format("woff2");
  font-weight: 100 1000;
  font-display: swap;
}

:root {
  --scale: 1;
  --accent: #ff5a1f;
  --panel-bg: #16181d;
  --panel-bg-top: #23272e;
  --strip-bg: rgba(13, 15, 19, 0.88);
  --ink: #f2f4f7;
  --ink-dim: #98a1ab;
  --edge: rgba(255, 255, 255, 0.08);
  --corner-red: #d92b2b;
  --corner-blue: #2b6bd9;
  --font-display: 'Archivo', Arial, sans-serif;
  --font-data: 'Saira', Arial, sans-serif;
}

html, body {
  margin: 0;
  width: 1920px;
  height: 1080px;
  overflow: hidden;
  background: transparent;
}

.mu-root {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  height: 560px;
  display: flex;
  align-items: flex-end;
  justify-content: center;
  gap: 4px;
  opacity: 0;
}

/* -- fighter sides ----------------------------------------------------- */
.mu-side {
  position: relative;
  width: 560px;
  height: 470px;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  background: linear-gradient(180deg, rgba(22, 24, 29, 0), var(--strip-bg) 62%);
}

.mu-photo {
  position: absolute;
  bottom: 150px;
  left: 50%;
  transform: translateX(-50%);
  width: 314px;
  height: 440px; /* 300:420 - the silhouette's own ratio, so nothing crops */
  object-fit: cover;
  object-position: top center;
}

.mu-nameblock {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 12px;
  padding: 26px 24px 30px;
  background: linear-gradient(180deg, var(--panel-bg-top), var(--panel-bg));
  box-shadow: inset 0 1px 0 var(--edge);
}

.mu-name {
  font-family: var(--font-display);
  font-weight: 800;
  font-size: 38px;
  letter-spacing: 0.06em;
  line-height: 1;
  color: var(--ink);
  text-transform: uppercase;
  white-space: nowrap;
}

.mu-underline {
  width: 64px;
  height: 4px;
}

.mu-underline-red { background: var(--corner-red); }
.mu-underline-blue { background: var(--corner-blue); }

.mu-record {
  font-family: var(--font-data);
  font-weight: 600;
  font-size: 21px;
  letter-spacing: 0.14em;
  line-height: 1;
  color: var(--ink-dim);
  font-variant-numeric: tabular-nums;
}

/* -- center column ------------------------------------------------------ */
.mu-center {
  position: relative;
  width: 380px;
  height: 470px;
  display: flex;
  flex-direction: column;
  align-items: center;
  padding-top: 44px;
  background: linear-gradient(180deg, var(--panel-bg-top), var(--panel-bg));
  border-top: 4px solid var(--accent);
  box-shadow: inset 0 1px 0 var(--edge), 0 18px 48px rgba(0, 0, 0, 0.5);
}

.mu-badge {
  font-family: var(--font-data);
  font-weight: 700;
  font-size: 20px;
  letter-spacing: 0.3em;
  line-height: 1;
  color: var(--accent);
  transform: translateX(0.15em);
  text-transform: uppercase;
}

.mu-division {
  font-family: var(--font-display);
  font-weight: 800;
  font-size: 34px;
  letter-spacing: 0.06em;
  line-height: 1.15;
  margin-top: 30px;
  color: var(--ink);
  text-transform: uppercase;
  text-align: center;
  max-width: 320px;
}

.mu-format {
  font-family: var(--font-data);
  font-weight: 500;
  font-size: 19px;
  letter-spacing: 0.16em;
  line-height: 1;
  margin-top: 16px;
  color: var(--ink-dim);
  text-transform: uppercase;
}

.mu-vs {
  font-family: var(--font-display);
  font-weight: 900;
  font-size: 96px;
  letter-spacing: 0.04em;
  line-height: 1;
  margin-top: auto;
  margin-bottom: 40px;
  color: rgba(255, 255, 255, 0.14);
}

