template.css:
/* Fight Night - stinger. Diagonal carbon panels with one accent blade; covers the
   frame at the midpoint (the edit point), then clears itself. */

@font-face {
  font-family: 'Archivo';
  src: url("fonts/archivo.woff2") format("woff2");
  font-weight: 100 1000;
  font-display: swap;
}
@font-face {
  font-family: 'Saira';
  src: url("fonts/saira.woff2") format("woff2");
  font-weight: 100 1000;
  font-display: swap;
}

:root {
  --scale: 1;
  --accent: #ff5a1f;
  --panel-bg: #16181d;
  --panel-bg-top: #23272e;
  --ink: #f2f4f7;
  --font-display: 'Archivo', Arial, sans-serif;
  --font-data: 'Saira', Arial, sans-serif;
}

html, body {
  margin: 0;
  width: 1920px;
  height: 1080px;
  overflow: hidden;
  background: transparent;
}

.stg-root {
  position: absolute;
  inset: 0;
  overflow: hidden;
  opacity: 0;
}

/* Panels are oversized and pre-rotated so the sweep never shows a corner. */
.stg-panel {
  position: absolute;
  top: -25%;
  height: 150%;
  width: 130%;
  transform: rotate(-14deg);
  transform-origin: center;
}

.stg-panel-a {
  left: -15%;
  background: linear-gradient(180deg, var(--panel-bg-top), var(--panel-bg));
}

.stg-panel-b {
  left: -15%;
  width: 3.5%;
  background: var(--accent);
}

.stg-panel-c {
  left: -15%;
  background: #0b0c0f;
}

.stg-mark {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 14px;
}

.stg-mark-name {
  font-family: var(--font-display);
  font-weight: 900;
  font-size: 150px;
  letter-spacing: 0.1em;
  line-height: 1;
  color: var(--ink);
  transform: translateX(0.05em);
}

.stg-mark-sub {
  font-family: var(--font-data);
  font-weight: 600;
  font-size: 26px;
  letter-spacing: 0.62em;
  line-height: 1;
  color: var(--accent);
  transform: translateX(0.31em);
}

template.js:
/* Fight Night - stinger. One-shot sweep: play() runs the whole pass and ends
   transparent; stop() only force-clears a pass in flight. No ?. or ?? (old CEF). */

(function () {
  var pass = null;

  window.update = function () {};

  window.play = function () {
    if (pass) { pass.kill(); }
    var xIn = 1920 * 1.35;
    pass = gsap.timeline();
    pass.set('#stg-root', { autoAlpha: 1 });
    pass.set(['.stg-panel-a', '.stg-panel-b', '.stg-panel-c'], { x: -xIn });
    pass.set('.stg-mark', { autoAlpha: 0 });
    // Sweep in: accent blade leads, carbon follows, near-black seals the frame.
    pass.to('.stg-panel-b', { x: 0, duration: 0.34, ease: 'power3.in' }, 0);
    pass.to('.stg-panel-a', { x: 0, duration: 0.36, ease: 'power3.in' }, 0.05);
    pass.to('.stg-panel-c', { x: 0, duration: 0.3, ease: 'power3.in' }, 0.16);
    // The mark flashes while the frame is covered - the edit point.
    pass.to('.stg-mark', { autoAlpha: 1, duration: 0.16, ease: 'power1.out' }, 0.48);
    pass.to('.stg-mark', { autoAlpha: 0, duration: 0.2, ease: 'power1.in' }, 0.92);
    // Sweep out the same direction, blade trailing.
    pass.to('.stg-panel-c', { x: xIn, duration: 0.34, ease: 'power3.out' }, 1.0);
    pass.to('.stg-panel-a', { x: xIn, duration: 0.36, ease: 'power3.out' }, 1.06);
    pass.to('.stg-panel-b', { x: xIn, duration: 0.32, ease: 'power3.out' }, 1.14);
    pass.set('#stg-root', { autoAlpha: 0 });
    pass.set(['.stg-panel-a', '.stg-panel-b', '.stg-panel-c'], { x: -xIn });
  };

  window.stop = function () {
    if (pass) { pass.kill(); pass = null; }
    gsap.set('#stg-root', { autoAlpha: 0 });
  };

  window.next = function () {};
})();
